WHERE u.deleted = 0

  AND u.role_code = #{roleCode}


  AND u.status = #{status}


  AND (
    u.username LIKE '%' + #{keyword} + '%'
    OR u.name   LIKE '%' + #{keyword} + '%'
    OR u.email  LIKE '%' + #{keyword} + '%'
    OR c.name   LIKE '%' + #{keyword} + '%'
  )
